import{_ as o,o as e,c as a,a0 as r}from"./chunks/framework.DCToIpx6.js";const p=JSON.parse('{"title":"REQ-BACKWARD-COMPAT — Backward Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"tests/test-cases/dynamic-column-config/REQ-BACKWARD-COMPAT.md","filePath":"tests/test-cases/dynamic-column-config/REQ-BACKWARD-COMPAT.md"}'),d={name:"tests/test-cases/dynamic-column-config/REQ-BACKWARD-COMPAT.md"};function n(s,t,c,i,l,m){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="req-backward-compat-—-backward-compatibility" tabindex="-1">REQ-BACKWARD-COMPAT — Backward Compatibility <a class="header-anchor" href="#req-backward-compat-—-backward-compatibility" aria-label="Permalink to &quot;REQ-BACKWARD-COMPAT — Backward Compatibility&quot;">​</a></h1><p><strong>Requerimiento:</strong> Consumidores existentes que no pasan las nuevas propiedades DEBEN seguir funcionando idénticamente — todas las columnas se renderizan, sin tooltips, clics sin efecto, filtro global busca en todas las columnas.</p><hr><h2 id="tc-backward-compat-01-config-legacy-sin-nuevas-propiedades-funciona" tabindex="-1">TC-BACKWARD-COMPAT-01: Config legacy sin nuevas propiedades funciona <a class="header-anchor" href="#tc-backward-compat-01-config-legacy-sin-nuevas-propiedades-funciona" aria-label="Permalink to &quot;TC-BACKWARD-COMPAT-01: Config legacy sin nuevas propiedades funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-BACKWARD-COMPAT-01</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-BACKWARD-COMPAT</td></tr><tr><td><strong>Prioridad</strong></td><td>Crítica</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (Regresión)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Array legacy de columnas: <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}]</code>. Sin propiedades <code>visible</code>, <code>tooltip</code>, <code>clickeable</code>, <code>filterable</code>, <code>detail</code>.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Inicializar el componente con el array legacy<br>2. Verificar renderizado<br>3. Hover sobre celda → sin tooltip<br>4. Clic en celda → sin evento<br>5. Escribir en filtro global → busca en todas las columnas</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>1. Columna <code>name</code> se renderiza<br>2. No hay tooltip al hacer hover<br>3. No se emite <code>cellClick</code> al hacer clic<br>4. Filtro global busca en columna <code>name</code></td></tr></tbody></table><hr><h2 id="tc-backward-compat-02-mezcla-legacy-nuevas-propiedades-no-rompe-legacy" tabindex="-1">TC-BACKWARD-COMPAT-02: Mezcla legacy + nuevas propiedades no rompe legacy <a class="header-anchor" href="#tc-backward-compat-02-mezcla-legacy-nuevas-propiedades-no-rompe-legacy" aria-label="Permalink to &quot;TC-BACKWARD-COMPAT-02: Mezcla legacy + nuevas propiedades no rompe legacy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-BACKWARD-COMPAT-02</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-BACKWARD-COMPAT</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Integración</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columnas: <code>[{key: &#39;legacy&#39;, header: &#39;Legacy&#39;}, {key: &#39;modern&#39;, header: &#39;Modern&#39;, clickeable: true, tooltip: &#39;Info&#39;}]</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Hover sobre celda <code>legacy</code> → sin tooltip<br>2. Hover sobre celda <code>modern</code> → tooltip aparece<br>3. Clic en <code>legacy</code> → sin evento<br>4. Clic en <code>modern</code> → <code>cellClick</code> emitido</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>Las columnas legacy se comportan como antes. Solo las columnas con nuevas propiedades tienen el comportamiento nuevo.</td></tr></tbody></table><hr><h2 id="tc-backward-compat-03-sin-filterable-el-filtro-global-funciona-como-antes" tabindex="-1">TC-BACKWARD-COMPAT-03: Sin filterable el filtro global funciona como antes <a class="header-anchor" href="#tc-backward-compat-03-sin-filterable-el-filtro-global-funciona-como-antes" aria-label="Permalink to &quot;TC-BACKWARD-COMPAT-03: Sin filterable el filtro global funciona como antes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-BACKWARD-COMPAT-03</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-BACKWARD-COMPAT</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Regresión</td></tr><tr><td><strong>Precondiciones</strong></td><td>Array legacy sin <code>filterable</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Escribir término en filtro global<br>2. Verificar que busca en todas las columnas</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>El comportamiento del filtro global es idéntico al anterior: busca en todas las columnas.</td></tr></tbody></table><hr><h2 id="tc-backward-compat-04-componente-sin-input-columns-no-se-rompe" tabindex="-1">TC-BACKWARD-COMPAT-04: Componente sin @Input columns no se rompe <a class="header-anchor" href="#tc-backward-compat-04-componente-sin-input-columns-no-se-rompe" aria-label="Permalink to &quot;TC-BACKWARD-COMPAT-04: Componente sin @Input columns no se rompe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-BACKWARD-COMPAT-04</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-BACKWARD-COMPAT</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Error Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Componente instanciado SIN pasar el input <code>columns</code> (o pasando <code>null</code>/<code>undefined</code>)</td></tr><tr><td><strong>Pasos</strong></td><td>1. Inicializar componente sin <code>columns</code><br>2. Verificar que no lanza error</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>El componente se inicializa sin errores. La tabla se renderiza vacía (sin columnas).</td></tr><tr><td><strong>Notas</strong></td><td>Compatibilidad con casos donde los datos llegan asincrónicamente.</td></tr></tbody></table>',14)])])}const b=o(d,[["render",n]]);export{p as __pageData,b as default};
